                      className="w-full px-4 py-2 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-600 outline-none"
                      value={editItem.image} onChange={e => setEditItem({...editItem, image: e.target.value})}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-bold text-slate-700">Extracto (Resumen corto para la lista)</label>
                  <textarea 
                    placeholder="Breve descripción que aparece en la tarjeta..." required rows={2}
                    className="w-full px-4 py-2 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-600 outline-none resize-none"
                    value={editItem.excerpt} onChange={e => setEditItem({...editItem, excerpt: e.target.value})}
                  ></textarea>
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-bold text-slate-700">Contenido Expandido (Lo que se lee al entrar)</label>
                  <textarea 
                    placeholder="Escribe aquí toda la noticia. Puedes usar saltos de línea..." required rows={8}
                    className="w-full px-4 py-2 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-600 outline-none"
                    value={editItem.fullContent} onChange={e => setEditItem({...editItem, fullContent: e.target.value})}
                  ></textarea>
                </div>

                <div className="flex gap-4 pt-4">
                  <button type="submit" className="flex-1 bg-blue-600 text-white py-3 rounded-xl font-bold hover:bg-blue-700 transition-all shadow-lg shadow-blue-100">
                    {editItem.id ? 'Guardar Cambios' : 'Publicar Noticia'}
                  </button>
                  <button type="button" onClick={() => setEditItem(null)} className="flex-1 bg-slate-100 text-slate-700 py-3 rounded-xl font-bold hover:bg-slate-200 transition-all">
                    Cancelar
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

