import React, { useState, useEffect } from 'react';
import { storageService } from '../services/storageService';

const Admin: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState('');
  const [pass, setPass] = useState('');
  const [activeTab, setActiveTab] = useState<'news' | 'services' | 'contact'>('news');

  // Data States
  const [news, setNews] = useState(storageService.getNews());
  const [services, setServices] = useState(storageService.getServices());
  const [contact, setContact] = useState(storageService.getContact());

  // Form States
  const [editItem, setEditItem] = useState<any>(null);
  const [editService, setEditService] = useState<any>(null);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (user === 'admin' && pass === 'nexus2024') {
      setIsAuthenticated(true);
    } else {
      alert('Credenciales incorrectas. (admin / nexus2024)');
    }
  };

  // --- News Logic ---
  const handleSaveNews = (e: React.FormEvent) => {
    e.preventDefault();
    let updated;
    if (editItem.id) {
      updated = news.map((n: any) => n.id === editItem.id ? editItem : n);
    } else {
      updated = [{ ...editItem, id: Date.now().toString() }, ...news];
    }
    setNews(updated);
    storageService.saveNews(updated);
    setEditItem(null);
  };

  const handleDeleteNews = (id: string) => {
    if (!window.confirm('¿Eliminar noticia?')) return;
    const updated = news.filter((n: any) => n.id !== id);
    setNews(updated);
    storageService.saveNews(updated);
  };

  // --- Services Logic ---
  const handleSaveService = (e: React.FormEvent) => {
    e.preventDefault();
    let updated;
    if (editService.id) {
      updated = services.map((s: any) => s.id === editService.id ? editService : s);
    } else {
      updated = [...services, { ...editService, id: Date.now().toString() }];
    }
    setServices(updated);
    storageService.saveServices(updated);
    setEditService(null);
  };

  const handleDeleteService = (id: string) => {
    if (!window.confirm('¿Eliminar servicio?')) return;
    const updated = services.filter((s: any) => s.id !== id);
    setServices(updated);
    storageService.saveServices(updated);
  };

  // --- Contact Logic ---
  const handleSaveContact = (e: React.FormEvent) => {
    e.preventDefault();
    storageService.saveContact(contact);
    alert('Datos de contacto actualizados correctamente');
  };

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-900 px-4">
        <div className="bg-white p-8 rounded-3xl shadow-2xl w-full max-w-md">
          <div className="text-center mb-8">
            <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white text-3xl font-bold mx-auto mb-4">N</div>
            <h1 className="text-2xl font-bold text-slate-900">Panel Nexus IT</h1>
          </div>
          <form onSubmit={handleLogin} className="space-y-4">
            <input type="text" placeholder="Usuario" className="w-full px-4 py-3 rounded-xl border border-slate-200" value={user} onChange={e => setUser(e.target.value)} />
            <input type="password" placeholder="Contraseña" className="w-full px-4 py-3 rounded-xl border border-slate-200" value={pass} onChange={e => setPass(e.target.value)} />
            <button className="w-full bg-blue-600 text-white py-3 rounded-xl font-bold">Entrar</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="pt-24 pb-20 min-h-screen bg-slate-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center mb-8">
          <h1 className="text-3xl font-bold text-slate-900">Administración</h1>
          <button onClick={() => setIsAuthenticated(false)} className="text-red-600 font-bold">Cerrar Sesión</button>
        </div>

        <div className="flex gap-4 mb-8 border-b border-slate-200 overflow-x-auto">
          {['news', 'services', 'contact'].map(tab => (
            <button 
              key={tab} 
              onClick={() => setActiveTab(tab as any)}
              className={`pb-4 px-4 font-bold whitespace-nowrap ${activeTab === tab ? 'border-b-2 border-blue-600 text-blue-600' : 'text-slate-400'}`}
            >
              {tab === 'news' ? 'Noticias' : tab === 'services' ? 'Servicios' : 'Datos de Contacto'}
            </button>
          ))}
        </div>

        {/* --- NEWS TAB --- */}
        {activeTab === 'news' && (
          <div className="space-y-6">
            <button onClick={() => setEditItem({ title: '', excerpt: '', fullContent: '', image: 'https://images.unsplash.com/photo-1518770660439-4636190af475', date: new Date().toLocaleDateString(), author: 'Admin' })} className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold">+ Nueva Noticia</button>
            <div className="bg-white rounded-2xl border overflow-hidden">
              <table className="w-full text-left">
                <thead className="bg-slate-50 border-b">
                  <tr><th className="px-6 py-4">Título</th><th className="px-6 py-4 text-right">Acciones</th></tr>
                </thead>
                <tbody className="divide-y">
                  {news.map((item: any) => (
                    <tr key={item.id}>
                      <td className="px-6 py-4">{item.title}</td>
                      <td className="px-6 py-4 text-right space-x-3">
                        <button onClick={() => setEditItem(item)} className="text-blue-600">Editar</button>
                        <button onClick={() => handleDeleteNews(item.id)} className="text-red-600">Borrar</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* --- SERVICES TAB --- */}
        {activeTab === 'services' && (
          <div className="space-y-6">
            <button onClick={() => setEditService({ title: '', category: 'hogar', icon: 'fa-microchip', desc: '', info: '' })} className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold">+ Nuevo Servicio</button>
            <div className="bg-white rounded-2xl border overflow-hidden">
              <table className="w-full text-left">
                <thead className="bg-slate-50 border-b">
                  <tr><th className="px-6 py-4">Servicio</th><th className="px-6 py-4">Categoría</th><th className="px-6 py-4 text-right">Acciones</th></tr>
