                <tbody className="divide-y">
                  {services.map((s: any) => (
                    <tr key={s.id}>
                      <td className="px-6 py-4 font-medium">{s.title}</td>
                      <td className="px-6 py-4 capitalize">{s.category}</td>
                      <td className="px-6 py-4 text-right space-x-3">
                        <button onClick={() => setEditService(s)} className="text-blue-600">Editar</button>
                        <button onClick={() => handleDeleteService(s.id)} className="text-red-600">Borrar</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* --- CONTACT TAB --- */}
        {activeTab === 'contact' && (
          <div className="bg-white p-8 rounded-3xl border shadow-sm max-w-2xl">
            <h2 className="text-2xl font-bold mb-6">Configuración de Contacto</h2>
            <form onSubmit={handleSaveContact} className="space-y-4">
              <div className="grid md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-bold text-slate-700 mb-1">Dirección</label>
                  <input type="text" className="w-full border p-2 rounded-lg" value={contact.address} onChange={e => setContact({...contact, address: e.target.value})} />
                </div>
                <div>
                  <label className="block text-sm font-bold text-slate-700 mb-1">Teléfono</label>
                  <input type="text" className="w-full border p-2 rounded-lg" value={contact.phone} onChange={e => setContact({...contact, phone: e.target.value})} />
                </div>
                <div>
                  <label className="block text-sm font-bold text-slate-700 mb-1">Email</label>
                  <input type="email" className="w-full border p-2 rounded-lg" value={contact.email} onChange={e => setContact({...contact, email: e.target.value})} />
                </div>
                <div>
                  <label className="block text-sm font-bold text-slate-700 mb-1">WhatsApp (con código país)</label>
                  <input type="text" className="w-full border p-2 rounded-lg" value={contact.whatsapp} onChange={e => setContact({...contact, whatsapp: e.target.value})} />
