    e.preventDefault();
    if (user === 'admin' && pass === 'nexus2024') {
      setIsAuthenticated(true);
    } else {
      alert('Credenciales incorrectas. (admin / nexus2024)');
    }
  };

  // --- News Logic ---
  const handleSaveNews = (e: React.FormEvent) => {
    e.preventDefault();
    let updated;
    if (editItem.id) {
      updated = news.map((n: any) => n.id === editItem.id ? editItem : n);
    } else {
      updated = [{ ...editItem, id: Date.now().toString() }, ...news];
    }
    setNews(updated);
    storageService.saveNews(updated);
    setEditItem(null);
  };

  const handleDeleteNews = (id: string) => {
    if (!window.confirm('¿Eliminar noticia?')) return;
    const updated = news.filter((n: any) => n.id !== id);
    setNews(updated);
    storageService.saveNews(updated);
  };

  // --- Services Logic ---
  const handleSaveService = (e: React.FormEvent) => {
    e.preventDefault();
    let updated;
    if (editService.id) {
      updated = services.map((s: any) => s.id === editService.id ? editService : s);
    } else {
      updated = [...services, { ...editService, id: Date.now().toString() }];
