import React, { useState } from 'react';
import { storageService } from '../services/storageService';

const Admin: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState('');
  const [pass, setPass] = useState('');
  const [activeTab, setActiveTab] = useState<'news' | 'services' | 'contact'>('news');

  // Feedback State
  const [feedback, setFeedback] = useState<{msg: string, type: 'success' | 'error'} | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  // Data States
  const [news, setNews] = useState(storageService.getNews());
  const [services, setServices] = useState(storageService.getServices());
  const [contact, setContact] = useState(storageService.getContact());

  // Form States
  const [editItem, setEditItem] = useState<any>(null);
  const [editService, setEditService] = useState<any>(null);

  const showFeedback = (msg: string, type: 'success' | 'error') => {
    setFeedback({ msg, type });
    setTimeout(() => setFeedback(null), 4000);
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (user === 'admin' && pass === 'Nexus_Admin_2025!#') {
      setIsAuthenticated(true);
    } else {
      alert('Credenciales incorrectas. Pista: Nexus_Admin_2025!#');
    }
  };

  // --- Generic Save Wrapper with loading simulation ---
  const simulateSave = async (saveFn: () => void, successMsg: string) => {
    setIsSaving(true);
    try {
      // Simulamos una pequeña latencia para que el usuario perciba el proceso
      await new Promise(resolve => setTimeout(resolve, 800));
      saveFn();
      showFeedback(successMsg, 'success');
    } catch (err) {
      showFeedback('Hubo un problema al procesar la solicitud', 'error');
    } finally {
      setIsSaving(false);
    }
  };

  // --- News Logic ---
  const handleSaveNews = (e: React.FormEvent) => {
    e.preventDefault();
    simulateSave(() => {
      let updated;
      if (editItem.id) {
        updated = news.map((n: any) => n.id === editItem.id ? editItem : n);
      } else {
        updated = [{ ...editItem, id: Date.now().toString() }, ...news];
      }
      setNews(updated);
      storageService.saveNews(updated);
      setEditItem(null);
    }, 'Noticia guardada exitosamente');
  };

  const handleDeleteNews = (id: string) => {
    if (!window.confirm('¿Eliminar esta noticia?')) return;
    simulateSave(() => {
      const updated = news.filter((n: any) => n.id !== id);
      setNews(updated);
      storageService.saveNews(updated);
    }, 'Noticia eliminada');
  };

  // --- Services Logic ---
