              </div>
              <button onClick={closeModal} className="mt-8 w-full bg-slate-900 text-white py-4 rounded-xl font-bold shadow-lg shadow-slate-200">Cerrar Detalle</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

